interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: { itemType: string; amount: number }[] };
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: (QuoteStep | ClaimStep)[];
}

const ITEM_BASE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const ITEM_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};

const COMPONENT_BASE = 25;
const COMPONENT_VALUE = 250;
const BLOCK_BASE = 60;

const PROCESSING_FEE = 5;

function isComponent(type: string): boolean {
  return type === "rune" || type === "moonstone";
}

function itemBasePremium(item: Item): number {
  if (isComponent(item.type)) return COMPONENT_BASE;
  return ITEM_BASE[item.type];
}

function componentBasePremium(components: Item[]): number {
  const counts: Record<string, number> = {};
  for (const c of components) {
    counts[c.type] = (counts[c.type] ?? 0) + 1;
  }
  let total = 0;
  for (const type of Object.keys(counts)) {
    const n = counts[type];
    total += Math.floor(n / 3) * BLOCK_BASE + (n % 3) * COMPONENT_BASE;
  }
  return total;
}

function ceilG(n: number): number {
  return Math.ceil(n);
}

export function quotePremium(customer: { yearsWithMHPCO: number }, items: Item[]): number {
  const mainItems = items.filter((i) => !isComponent(i.type));
  const components = items.filter((i) => isComponent(i.type));

  let base = 0;
  for (const item of mainItems) {
    let p = itemBasePremium(item);
    if (item.cursed) p += 0.5 * p;
    if ((item.enchantment ?? 0) >= 5) p += 0.3 * itemBasePremium(item);
    base += p;
  }
  base += componentBasePremium(components);

  let total = base;
  if (customer.yearsWithMHPCO >= 2) total -= 0.2 * base;
  total += PROCESSING_FEE;

  return ceilG(total);
}

export function processScenario(scenario: Scenario): { results: unknown[] } {
  const results: unknown[] = [];
  const policies: { items: Item[]; insuranceSum: number; cap: number; remainingCap: number }[] = [];

  for (const step of scenario.steps) {
    if (step.op === "quote") {
      const premium = quotePremium(scenario.customer, step.items);
      const insuranceSum = step.items.reduce((sum, i) => sum + (isComponent(i.type) ? COMPONENT_VALUE : ITEM_VALUE[i.type]), 0);
      const cap = insuranceSum * 2;
      policies.push({ items: step.items, insuranceSum, cap, remainingCap: cap });
      results.push({ premium });
    }
  }

  return { results };
}

interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: { itemType: string; amount: number }[] };
}

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: (QuoteStep | ClaimStep)[];
}

const ITEM_BASE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const ITEM_VALUE: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};

const COMPONENT_BASE = 25;
const COMPONENT_VALUE = 250;
const BLOCK_BASE = 60;
const FEE = 5;
const DEDUCTIBLE = 100;

function isComponent(type: string): boolean {
  return type === "rune" || type === "moonstone";
}

function isKnownType(type: string): boolean {
  return isComponent(type) || type in ITEM_BASE;
}

function itemBasePremium(item: Item): number {
  return isComponent(item.type) ? COMPONENT_BASE : ITEM_BASE[item.type];
}

function itemValue(item: Item): number {
  return isComponent(item.type) ? COMPONENT_VALUE : ITEM_VALUE[item.type];
}

function policyBasePremium(items: Item[]): number {
  let base = 0;
  const componentCounts: Record<string, number> = {};
  for (const item of items) {
    if (!isKnownType(item.type)) {
      throw new Error(`unknown item type: ${item.type}`);
    }
    if (isComponent(item.type)) {
      componentCounts[item.type] = (componentCounts[item.type] ?? 0) + 1;
    } else {
      base += itemBasePremium(item);
    }
  }
  for (const type of Object.keys(componentCounts)) {
    const count = componentCounts[type];
    if (count === 3) {
      base += BLOCK_BASE;
    } else {
      base += count * COMPONENT_BASE;
    }
  }
  return base;
}

function itemSurcharges(items: Item[]): number {
  let surcharge = 0;
  for (const item of items) {
    if (isComponent(item.type)) continue;
    const base = itemBasePremium(item);
    if (item.cursed) surcharge += 0.5 * base;
    if ((item.enchantment ?? 0) >= 5) surcharge += 0.3 * base;
  }
  return surcharge;
}

function insuranceSum(items: Item[]): number {
  let sum = 0;
  for (const item of items) {
    if (!isKnownType(item.type)) {
      throw new Error(`unknown item type: ${item.type}`);
    }
    sum += itemValue(item);
  }
  return sum;
}

function quotePremium(
  customer: { yearsWithMHPCO: number },
  items: Item[],
  contractIndex: number,
): number {
  const base = policyBasePremium(items);
  const surcharge = itemSurcharges(items);

  let adjustment = 0.1 * base;
  if (customer.yearsWithMHPCO >= 2) adjustment -= 0.2 * base;
  if (contractIndex >= 1) adjustment -= 0.15 * base;

  const total = base + surcharge + adjustment + FEE;
  return Math.ceil(total);
}

function payoutForClaim(
  policyItems: Item[],
  damages: { itemType: string; amount: number }[],
): number {
  const policyTypeCounts: Record<string, number> = {};
  for (const item of policyItems) {
    policyTypeCounts[item.type] = (policyTypeCounts[item.type] ?? 0) + 1;
  }

  const damageTypeCounts: Record<string, number> = {};
  for (const d of damages) {
    if (d.amount < 0) {
      throw new Error(`negative damage amount: ${d.amount}`);
    }
    if (!isKnownType(d.itemType)) {
      throw new Error(`unknown item type: ${d.itemType}`);
    }
    if (!(d.itemType in policyTypeCounts)) {
      throw new Error(`damaged item not in policy: ${d.itemType}`);
    }
    damageTypeCounts[d.itemType] = (damageTypeCounts[d.itemType] ?? 0) + 1;
  }

  for (const type of Object.keys(damageTypeCounts)) {
    if (damageTypeCounts[type] > (policyTypeCounts[type] ?? 0)) {
      throw new Error(`more damages of type ${type} than covered`);
    }
  }

  let payout = 0;
  for (const d of damages) {
    const item = policyItems.find((i) => i.type === d.itemType);
    const enchantment = item?.enchantment ?? 0;
    const factor = enchantment >= 8 ? 0.5 : 1;
    const raw = d.amount * factor;
    payout += Math.max(0, raw - DEDUCTIBLE);
  }
  return payout;
}

interface Policy {
  items: Item[];
  insuranceSum: number;
  cap: number;
  remainingCap: number;
}

export function processScenario(
  scenario: Scenario,
): { results: unknown[] } {
  const results: unknown[] = [];
  const policies: Policy[] = [];
  let contractIndex = 0;

  for (const step of scenario.steps) {
    if (step.op === "quote") {
      const premium = quotePremium(scenario.customer, step.items, contractIndex);
      contractIndex += 1;
      const sum = insuranceSum(step.items);
      const cap = sum * 2;
      policies.push({ items: step.items, insuranceSum: sum, cap, remainingCap: cap });
      results.push({ premium });
    } else {
      const policy = policies[step.policy];
      const payoutRaw = payoutForClaim(policy.items, step.incident.damages);
      const payout = Math.min(Math.floor(payoutRaw), policy.remainingCap);
      policy.remainingCap -= payout;
      results.push({ payout, remainingCap: policy.remainingCap });
    }
  }

  return { results };
}

